--
-- Name: order_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.order_items (
    id integer NOT NULL,
    order_id integer,
    product_id integer,
    department text,
    description text NOT NULL,
    quantity integer NOT NULL,
    unit_price numeric(10,2) NOT NULL,
    amount numeric(10,2) NOT NULL,
    notes text,
    vendor_order_id integer,
    discount_amount numeric(10,2) DEFAULT '0'::numeric NOT NULL,
    discount_reason text,
    variant_id integer,
    fabric_id integer,
    product_sku_snapshot text,
    variant_sku_snapshot text,
    variant_name_snapshot text,
    fabric_item_number_snapshot text,
    fabric_name_snapshot text,
    fabric_vendor_id integer,
    fabric_vendor_order_id integer,
    use_inventory boolean DEFAULT false NOT NULL,
    inventory_qty_used integer DEFAULT 0 NOT NULL,
    finish_id integer,
    finish_code_snapshot text,
    finish_name_snapshot text,
    fabric_brand_snapshot text,
    fabric_grade_snapshot text,
    unit_msrp_snapshot numeric(10,2),
    weight_snapshot numeric(10,2),
    CONSTRAINT order_items_fabric_requires_product CHECK (((fabric_id IS NULL) OR (product_id IS NOT NULL))),
    CONSTRAINT order_items_fabric_snapshots_required CHECK (((fabric_id IS NULL) OR ((fabric_item_number_snapshot IS NOT NULL) AND (fabric_name_snapshot IS NOT NULL)))),
    CONSTRAINT order_items_fabric_vendor_requires_fabric CHECK (((fabric_vendor_id IS NULL) OR (fabric_id IS NOT NULL))),
    CONSTRAINT order_items_fabric_vo_requires_fabric_vendor CHECK (((fabric_vendor_order_id IS NULL) OR (fabric_vendor_id IS NOT NULL))),
    CONSTRAINT order_items_product_sku_snapshot_required CHECK (((product_id IS NULL) OR (product_sku_snapshot IS NOT NULL))),
    CONSTRAINT order_items_variant_requires_product CHECK (((variant_id IS NULL) OR (product_id IS NOT NULL))),
    CONSTRAINT order_items_variant_snapshots_required CHECK (((variant_id IS NULL) OR ((variant_sku_snapshot IS NOT NULL) AND (variant_name_snapshot IS NOT NULL))))
);


